3: package telemetry;
4: 
5: // One measurement of one network device at one moment.
6: message Metric {
7:   string device_id           = 1;  // unique name, e.g. "core-router-1"
8:   string device_type         = 2;  // "router", "switch", "host" ...
9:   string interface           = 3;  // interface the numbers belong to, e.g. "eth0"
10:   int64  timestamp_ms        = 4;  // when the agent measured (unix epoch, milliseconds)
11:   double rx_bps              = 5;  // bits per second received
12:   double tx_bps              = 6;  // bits per second sent
13:   double capacity_bps        = 7;  // link capacity in bits per second
14:   double latency_ms          = 8;  // round-trip latency; negative means "not available"
15:   double packet_loss_pct     = 9;  // 0..100; negative means "not available"
16: }
17: 
18: message MetricBatch {
19:   repeated Metric metrics = 1;
20: }
21: 
22: message Ack {
23:   int64  accepted = 1;   // how many metrics the backend accepted
24:   int64  rejected = 2;   // how many were invalid
25: }
26: 
27: service Telemetry {
28:   // Long-lived stream: an agent keeps one connection open and pushes a Metric
29:   // every interval (this is the main path).
30:   rpc Stream (stream Metric) returns (Ack);
31: 
32:   // One-shot call: send a batch in a single request (useful for tests and tools).
33:   rpc Publish (MetricBatch) returns (Ack);
34: }

